+  },
+  {
+    id: 'foreign',
+    projectId: 'e2e-open-foreign',
+    describe: 'valid SQLite that is not an Arq project is refused, not initialised over',
+    seedFirst: { type: 'makeForeignSqlite', applicationId: 0x12345678 },
+    expect: (result) => result.status === 'rejected',
+  },
