+  try {
+    await page.goto(`http://127.0.0.1:${port}/bench/e2e-arq-open.html`, {
+      waitUntil: 'domcontentloaded',
+    });
+    await page.waitForFunction(() => window.__ARQ_E2E_OPEN_READY__ === true, { timeout: 30_000 });
