+<!doctype html>
+<html lang="en">
+  <head>
+    <meta charset="utf-8" />
+    <title>arqfs end-to-end project open over a real Worker and OPFS (ARQ-217)</title>
+  </head>
+  <body>
+    <script type="module">
+      // Every request runs on a brand new Worker that is terminated before the
+      // promise resolves. The file therefore has to survive Worker teardown in
+      // OPFS between the seeding step and the open under test - if it did not,
+      // the second Worker would see a fresh empty file and every case would
+      // report "opened", which is exactly the false pass this check must not
+      // be able to produce.
+      let nextId = 1;
+
+      function runOnFreshWorker(scriptUrl, projectId, request, timeoutMs = 30_000) {
+        return new Promise((resolve, reject) => {
+          const worker = new Worker(`${scriptUrl}?project=${encodeURIComponent(projectId)}`, {
+            type: 'module',
+          });
+          const timer = setTimeout(() => {
+            worker.terminate();
+            reject(new Error(`worker timed out after ${timeoutMs}ms`));
+          }, timeoutMs);
+          worker.onmessage = (event) => {
+            clearTimeout(timer);
+            worker.terminate();
+            resolve(event.data);
+          };
+          worker.onerror = (event) => {
+            clearTimeout(timer);
+            worker.terminate();
+            reject(new Error(event.message || 'worker error'));
+          };
+          worker.postMessage({ id: nextId++, ...request });
+        });
+      }
+
+      // The real bundled arqfs-worker-entry.ts, not a reimplementation of it.
+      window.__arqOpen = (projectId) =>
+        runOnFreshWorker('./e2e-arq-open-worker.js', projectId, { type: 'open' });
+
+      window.__arqSeed = (projectId, request) =>
+        runOnFreshWorker('./e2e-arq-open-seed-worker.js', projectId, request);
+
+      window.__ARQ_E2E_OPEN_READY__ = true;
+    </script>
+  </body>
+</html>

